def longest_integer_common_prefix(arr1,arr2):
    prefixes=set()
    for value in arr1:
        while value:prefixes.add(value);value//=10
    answer=0
    for value in arr2:
        while value and value not in prefixes:value//=10
        if value:answer=max(answer,len(str(value)))
    return answer

